css:
.race-card {
  display: flex;
  align-items: center;
  gap: 20px;
  max-width: 400px;
  width: 90%;
  padding: 20px 30px;
  border-radius: 35px;
  background: rgb(0, 0, 0);
  backdrop-filter: blur(8px);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.3);
  border: 1px solid rgba(119, 119, 119, 0.2);
  color: #fff;
  font-family: "Inter", sans-serif;
}

.track-container {
  width: 55%;
  text-align: center;
  position: relative;
}

.track-svg {
  width: 100%;
  height: auto;
  transform: rotate(-15deg);
}

.sector-text {
  margin-top: 10px;
  font-size: 14px;
  color: #d3d3d3;
}

.lap-times {
  width: 45%;
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 16px;
  color: #ff8ab4;
}

.lap-times div {
  display: flex;
  justify-content: space-between;
}

.lap-times .current-lap {
  font-weight: bold;
  font-size: 18px;
  color: #fff;
}

.lap-times span:first-child {
  color: #a0a0a0;
}

/* Responsivní drobnosti */
@media (max-width: 480px) {
  .race-card {
    flex-direction: column;
    width: 90%;
  }
  .track-container,
  .lap-times {
    width: 100%;
  }
}
